"""Read-only candidate checks; every generated byte remains in the host root."""
import datetime, hashlib, json, os, pathlib, subprocess, tempfile

workspace=pathlib.Path(__file__).resolve().parents[2]
root=pathlib.Path(os.environ['SERVICE_UI_RUNTIME_ROOT']).resolve(strict=True)
assert root.is_dir() and not root.is_relative_to(workspace) and not workspace.is_relative_to(root)
out=pathlib.Path(tempfile.mkdtemp(prefix='c-',dir=root))
paths=['frontend/src','frontend/scripts','frontend/styles.css','frontend/package.json','frontend/package-lock.json']
def manifest():
    files=[]
    for name in paths:
        path=workspace/name
        files.extend(path.rglob('*') if path.is_dir() else [path])
    return {p.relative_to(workspace).as_posix():hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(files) if p.is_file()}
before=manifest()
(out/'source-before.json').write_text(json.dumps(before,indent=2),encoding='utf-8')
commands=[
 'npm --prefix frontend run check:task-view',
 'npm --prefix frontend run check:task-center-model',
 'npm --prefix frontend run build',
 'node frontend/scripts/check-mission-budget.browser.mjs',
 'node frontend/scripts/check-task-center.browser.mjs',
 'node frontend/scripts/remediation/service-ui-browser.mjs',
 'node frontend/scripts/remediation/service-ui-build-modes.mjs',
]
records=[]
for index,command in enumerate(commands):
    start=datetime.datetime.now(datetime.timezone.utc).isoformat()
    result=subprocess.run(['cmd','/d','/s','/c',command],cwd=workspace,capture_output=True)
    output=result.stdout+result.stderr
    log=out/f'{index+1}.log'
    log.write_bytes(output)
    record={'command':command,'exit_code':result.returncode,'evidence':str(log),'output_sha256':hashlib.sha256(output).hexdigest(),'started_at':start,'finished_at':datetime.datetime.now(datetime.timezone.utc).isoformat()}
    records.append(record)
    (out/'commands.json').write_text(json.dumps(records,indent=2),encoding='utf-8')
    print(json.dumps(record),flush=True)
after=manifest()
(out/'source-after.json').write_text(json.dumps(after,indent=2),encoding='utf-8')
changed=[name for name in sorted(set(before)|set(after)) if before.get(name)!=after.get(name)]
(out/'candidate-integrity.json').write_text(json.dumps({'unchanged':not changed,'changed_files':changed},indent=2),encoding='utf-8')
print('MISSION_UI_CHECK_EVIDENCE='+str(out),flush=True)
raise SystemExit(0 if not changed and all(record['exit_code']==0 for record in records) else 1)
